import React, { useEffect, useState } from 'react';
import { collection, getDocs } from 'firebase/firestore';
import { db } from '../services/firebaseConfig';
import { BarChart, Bar, PieChart, Pie, Cell, Tooltip, Legend, XAxis, ResponsiveContainer } from 'recharts';

export default function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const [fixedExpenses, setFixedExpenses] = useState([]); // eslint-disable-line no-unused-vars
  const [summary, setSummary] = useState({ entradas: 0, saidas: 0, fixos: 0, saldo: 0 });
  const [expenseDetails, setExpenseDetails] = useState([]);
  const [incomeDetails, setIncomeDetails] = useState([]);
  const [dataLoaded, setDataLoaded] = useState(false); // flag de carregamento

  // 🔹 Carrega transações e gastos fixos do Firestore
  useEffect(() => {
    const loadData = async () => {
      try {
        const transSnap = await getDocs(collection(db, 'transactions'));
        const transData = transSnap.docs.map(doc => ({ id: doc.id, ...doc.data() }));

        const fixSnap = await getDocs(collection(db, 'fixed_expenses'));
        const fixData = fixSnap.docs.map(doc => ({ id: doc.id, ...doc.data() }));

        setTransactions([...transData]); // força nova referência de array
        setFixedExpenses([...fixData]);

        const entradas = transData
          .filter(t => (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === 'entrada')
          .reduce((acc, t) => acc + parseFloat(t.amount || t.valor || 0), 0);

        const saidas = transData
          .filter(t => (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === 'saida')
          .reduce((acc, t) => acc + parseFloat(t.amount || t.valor || 0), 0);

        const fixos = fixData.reduce((acc, f) => acc + parseFloat(f.value || f.valor || 0), 0);

        setSummary({ entradas, saidas, fixos, saldo: entradas - (saidas + fixos) });

        setDataLoaded(true); // marca como carregado
      } catch (err) {
        console.error('Erro ao carregar dados:', err);
      }
    };

    loadData();
  }, []);

  // 🔹 Calcula detalhes para os gráficos de pizza
  useEffect(() => {
    if (!dataLoaded) return;

    const expDetails = transactions
      .filter(t => (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === 'saida')
      .map(t => ({
        name: t.category || 'Sem categoria',
        value: parseFloat(t.amount || t.valor || 0),
        color: t.color || '#999'
      }));

    const incDetails = transactions
      .filter(t => (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === 'entrada')
      .map(t => ({
        name: t.category || 'Sem categoria',
        value: parseFloat(t.amount || t.valor || 0),
        color: t.color || '#999'
      }));

    setExpenseDetails([...expDetails]); // cria nova referência
    setIncomeDetails([...incDetails]);
  }, [transactions, dataLoaded]);

  const COLORS = ['#22c55e', '#ef4444', '#3b82f6', '#facc15', '#a855f7', '#000000'];

  const barData = [
    { name: 'Entradas', valor: summary.entradas },
    { name: 'Saídas', valor: summary.saidas },
    { name: 'Fixos', valor: summary.fixos },
  ];

  if (!dataLoaded) {
    return <p className="text-center text-gray-400 mt-6">Carregando dados...</p>;
  }

  return (
    <div className="p-6 text-white">
      <h2 className="text-2xl font-bold mb-4">📊 Dashboard Financeiro</h2>

      <div className="grid grid-cols-4 gap-4 mb-6">
        <div className="bg-green-800 p-4 rounded-lg">Entradas: <strong>R$ {summary.entradas.toFixed(2)}</strong></div>
        <div className="bg-red-800 p-4 rounded-lg">Saídas: <strong>R$ {summary.saidas.toFixed(2)}</strong></div>
        <div className="bg-blue-800 p-4 rounded-lg">Fixos: <strong>R$ {summary.fixos.toFixed(2)}</strong></div>
        <div className={`p-4 rounded-lg ${summary.saldo >= 0 ? 'bg-green-600' : 'bg-red-600'}`}>
          Saldo: <strong>R$ {summary.saldo.toFixed(2)}</strong>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-6">
        {/* Gráfico de Barras */}
        <div className="bg-gray-900 p-4 rounded-lg">
          <h3 className="mb-2 font-bold text-lg">Resumo Geral</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart key={Date.now()} data={barData}>
              <XAxis dataKey="name" tick={{ fill: '#ddd' }} />
              <Tooltip cursor={{ fill: 'rgba(255,255,255,0.1)' }} />
              <Bar dataKey="valor" radius={[8, 8, 0, 0]}>
                {barData.map((entry, index) => (
                  <Cell key={`bar-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Gráfico de Pizza - Saídas */}
        <div className="bg-gray-900 p-4 rounded-lg">
          <h3 className="mb-2 font-bold text-lg">Detalhamento de Saídas</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart key={Date.now()}>
              <Pie data={expenseDetails} dataKey="value" nameKey="name" outerRadius={100}>
                {expenseDetails.map((entry, index) => (
                  <Cell key={`slice-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>

        {/* Gráfico de Pizza - Entradas */}
        <div className="bg-gray-900 p-4 rounded-lg col-span-2">
          <h3 className="mb-2 font-bold text-lg">Detalhamento de Entradas</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart key={Date.now()}>
              <Pie data={incomeDetails} dataKey="value" nameKey="name" outerRadius={100}>
                {incomeDetails.map((entry, index) => (
                  <Cell key={`slice-income-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}
